def decode(string):
    """Decode a run-length encoded string."""
    result = []
    i = 0
    n = len(string)
    while i < n:
        # If there's a number, parse the full count (could be multiple digits)
        if string[i].isdigit():
            j = i
            while j < n and string[j].isdigit():
                j += 1
            count = int(string[i:j])
            if j < n:
                # Next character (could be a space) is the one to repeat
                result.append(string[j] * count)
                i = j + 1
            else:
                # Malformed input (digits at end) - ignore
                i = j
        else:
            # No leading number => single occurrence
            result.append(string[i])
            i += 1
    return ''.join(result)


